function draw() {
	randomSeed(seed);
	clear();

	let layers = 4;
	for (let l = 0; l < layers; l++) {
		let tOffset = t + l * 100;
		let rezLayer = rez * (1 + l * 0.3);
		let alpha = 255; // / (l + 1);
		let sizeScale = 1 - l * 0.1;
		let plus = int(random(20, 50));

		for (let i = xOff; i < width - xOff; i += plus) {
			for (let j = yOff; j < height - yOff; j += plus) {
				let n = noise(i * rezLayer, j * rezLayer + tOffset);
				let size = plus * (n > 0.35 ? 0.25 : 1.25) * sizeScale;

				// 根据层来决定运动方式
				let offsetX = 0;
				let offsetY = 0;

				switch (l) {
					case 0: // 圆形层：左右 sin 波
						offsetX = sin(t + j * 0.01) * 10;
						break;

					case 1: // 线条层：垂直 noise 流动
						offsetY = map(noise(i * 0.01, t), 0, 1, -15, 15);
						break;

					case 2: // 方形层：旋涡感
						offsetX = cos(t + i * 0.005 + j * 0.005) * 8;
						offsetY = sin(t + j * 0.005 - i * 0.005) * 8;
						break;

					case 3: // 三角层：缓慢下沉
						offsetY = t * 20 % height;
						break;
				}

				let cx = i + offsetX;
				let cy = j + offsetY;

				let c = color(random(colors));
				c.setAlpha(alpha);

				push();
				translate(cx, cy);

				switch (l) {
					case 0:
						noStroke();
						fill(c);
						ellipse(0, 0, size / 2, size / 2);
						break;

					case 1:
						stroke(c);
						noFill();
						strokeWeight(random(0.5, 1.5));
						line(-size / 2, -size / 2, size / 2, size / 2);
						break;

					case 2:
						noStroke();
						fill(c);
						rectMode(CENTER);
						rect(0, 0, size, size);
						break;

					case 3:
						noStroke();
						fill(c);
						let h = size * sqrt(3) / 2;
						triangle(
							0, -h / 2,
							-size / 2, h / 2,
							size / 2, h / 2
						);
						break;
				}
				pop();
			}
		}
	}

	t += 0.01;
}

